// One item per account: the endpoint that lists its posts, and how it is named.
// Find other endpoints with the DataXAPI node's Any Endpoint → Find (free).
return [
  { json: { endpoint: 'douyin.users.videos.list', params: { id: 'MS4wLjABAAAA_REPLACE_ME' } } },
  { json: { endpoint: 'xiaohongshu.users.notes.list', params: { url: 'https://www.xiaohongshu.com/user/profile/REPLACE_ME' } } },
  { json: { endpoint: 'tiktok.users.videos.list', params: { username: 'REPLACE_ME' } } },
];

// Keep only items not seen in earlier runs. Static data persists only when the
// workflow is active (production runs), not in manual test runs.
const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || [];
const known = new Set(seen.ids);
const fresh = $input.all().filter((item) => item.json.id && !known.has(item.json.id));
seen.ids = [...seen.ids, ...fresh.map((item) => item.json.id)].slice(-2000);
return fresh.map((item) => {
  const p = item.json;
  const who = (p.author && (p.author.name || p.author.username)) || 'An account';
  const text = (p.title || p.text || '').slice(0, 200);
  return { json: { text: `${who} posted: ${text}\n${p.url || ''}` } };
});
